import os
import tempfile
from shutil import copyfile


def copy_file_to_new_location(current_path, new_location):
    """
    Save a file by copying it to a new location and removing the original.

    :param str current_path: Path to the file that should be copied and then removed.
    :param str new_location: Path where the file should be saved (copied to).
    """
    copyfile(current_path, new_location)
    os.remove(current_path)


def read_from_file(path):
    """
    Read the contents of a text file.

    :param str path: Path to the file whose contents should be read.
    :returns: The entire file contents as a string.
    :rtype: str
    """
    with open(path, 'r+') as file:
        return file.read()


def save_to_file(content, target_path, should_decode=True):
    """
    Save the content of a file to a new location.
    If the content is in bytes and should_decode is True, it will be decoded before saving.
    If the target directory does not exist, it will be created.

    :param Union[str, bytes] content: Content to be saved.
    :param str target_path: Path where the file should be saved.
    :param bool should_decode: Whether to decode the content if it is in bytes.
    """
    if isinstance(content, bytes) and should_decode:
        content = content.decode()

    if not os.path.exists(target_path):
        dir_name = os.path.dirname(target_path)
        os.makedirs(dir_name, exist_ok=True)

    with open(target_path, "w" if isinstance(content, str) else "wb") as f:
        f.write(content)


def save_bytes_to_file_and_return_path(content, target_file_name, target_dir=None):
    """
    Save a byte string to a file in the given location with

    :param bytes content: Byte string to be saved.
    :param str target_file_name: Name of the file that should be saved.
    :param str target_dir: Directory where the file should be saved, if not given the file will be saved in the /tmp

    :returns: path to the saved file.
    """
    if target_dir:
        path = os.path.join(target_dir, target_file_name)

    else:
        file_descriptor, tmp_path = tempfile.mkstemp()
        os.close(file_descriptor)
        os.remove(tmp_path)

        path = os.path.join(os.path.dirname(tmp_path), target_file_name)

    with open(path, "wb") as f:
        f.write(content)

    return path

